import React, { useState } from 'react';

const HelloWorldLauncher = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [message, setMessage] = useState('');

  const handleShow = () => {
    setIsVisible(true);
    // Simulate fetching from the new endpoint
    fetch('/helloworld')
      .then(response => {
        if (!response.ok) {
          throw new Error('Network response was not ok');
        }
        return response.text(); // Assuming the endpoint returns text
      })
      .then(data => {
        setMessage(data);
        // Simple animation simulation by setting a timeout
        setTimeout(() => {
          setMessage('✨ Hello World! (Animated) ✨');
        }, 500);
      })
      .catch(error => {
        console.error('Error fetching helloworld:', error);
        setMessage('Error loading message from /helloworld endpoint.');
      });
  };

  return (
    <div>
      {/* CRITICAL UNBREAKABLE CODE: Must render a launcher button if visibility is toggled */}
      {!isVisible && (
        <button onClick={handleShow} style={{ padding: '10px 20px', fontSize: '16px', cursor: 'pointer' }}>
          🚀 Launch Animated Hello World Feature
        </button>
      )}

      {/* Modal/Visible Content */}
      {isVisible && (
        <div style={{ border: '2px solid #4CAF50', padding: '20px', marginTop: '20px', backgroundColor: '#e8f5e9' }}>
          <h3>Feature Loaded</h3>
          <p style={{ fontSize: '24px', color: '#2e7d32' }}>{message}</p>
          <button onClick={() => setIsVisible(false)} style={{ marginTop: '15px', padding: '8px 15px' }}>
            Close Feature
          </button>
        </div>
      )}
    </div>
  );
};

export default HelloWorldLauncher;
